import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(0)
        return

    n = int(data[0])
    k = int(data[1])

    if k == 0:
        print(0)
        return

    a = list(map(int, data[2:2+k]))

    seen = set()
    crashes = 0

    for num in a:
        remainder = num % k
        if remainder in seen:
            crashes += 1
        else:
            seen.add(remainder)

    print(crashes)

if __name__ == "__main__":
    main()
